using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows;using WinBoard;
class DockActivationSmoke {
 static Board board;static Application app;static Type entryType=typeof(Board).GetNestedType("DockEntry",BindingFlags.NonPublic);
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static object Entry(IntPtr handle,string path){var e=Activator.CreateInstance(entryType,true);entryType.GetField("Pin").SetValue(e,new Shortcut{Name="test",Path=path});var a=new RunningApp{Path="invalid-fallback.exe"};a.Windows.Add(new RunningWindow{Handle=handle,Title="fixture"});entryType.GetField("App").SetValue(e,a);return e;}
 static void Open(object e){typeof(Board).GetMethod("OpenDockEntry",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(board,new[]{e});}
 [STAThread]static void Main(string[] args){if(args.Length>0){File.AppendAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launched.txt"),args[0]+"\n");return;}try{var prefs=Storage.Normalize(new Preferences{Version=2,HideTaskbarWhileRunning=false});foreach(var w in prefs.Widgets.Windows)w.Enabled=false;Storage.Write(Path.GetFullPath("data/settings.json"),prefs);app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};board=new Board();board.Loaded+=async(s,e)=>{try{var w=new Window{Title="Dock activation fixture",Width=300,Height=180};w.Show();var h=new System.Windows.Interop.WindowInteropHelper(w).Handle;var entry=Entry(h,Path.GetFullPath("fixture.lnk"));w.WindowState=WindowState.Minimized;Open(entry);await Task.Delay(650);Check(!RunningApps.IsIconic(h)&&w.IsVisible,"Minimized fixture did not restore");Check(!File.Exists("launched.txt"),"Restoring launched duplicate process");w.Hide();Open(entry);await Task.Delay(650);Check(File.ReadAllText("launched.txt").Trim()=="original-shortcut","Hidden window did not use original shortcut/arguments");w.Close();Open(entry);await Task.Delay(650);Check(File.ReadAllLines("launched.txt").Length==2,"Destroyed handle did not relaunch");entryType.GetField("App").SetValue(entry,null);Open(entry);await Task.Delay(650);Check(File.ReadAllLines("launched.txt").Length==3,"Exited application did not launch");File.WriteAllText("result.txt","PASS: minimize restores without launch; hidden/dead/absent windows launch original shortcut with arguments.");}catch(Exception ex){File.WriteAllText("error.txt",ex.ToString());Environment.ExitCode=1;}finally{typeof(Board).GetMethod("Quit",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(board,null);}};app.Run(board);}catch(Exception ex){File.WriteAllText("error.txt",ex.ToString());Environment.ExitCode=1;}}
}
